*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f5f4e9;background:#101813;font-synthesis:none;--lime:#d5f36c;--paper:#f5f4e9;--muted:#a5aa97;--panel:rgba(13,20,17,.88)} html,body,#game-wrap{margin:0;width:100%;height:100%;overflow:hidden} body{min-width:320px} button,select{font:inherit} button{cursor:pointer} #game-wrap{position:relative;background:#131c17} #game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block} #vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,rgba(7,12,10,.18) 100%);z-index:1}.hud{z-index:3;position:absolute}.hidden{display:none!important}
#start-screen{position:absolute;inset:0;z-index:5;overflow:auto;background:linear-gradient(90deg,rgba(8,15,12,.95) 0%,rgba(8,15,12,.82) 48%,rgba(8,15,12,.19) 100%),linear-gradient(0deg,rgba(8,15,12,.75),transparent 30%),url('https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=2000&q=85') center/cover;color:var(--paper)}.menu-grain{position:absolute;inset:0;pointer-events:none;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")} .menu-nav{position:absolute;left:6.2%;right:6.2%;top:5%;display:flex;justify-content:space-between;align-items:center}.brand-mark{display:flex;align-items:center;gap:10px;font:700 11px/1 'Space Grotesk',sans-serif;letter-spacing:1.6px}.brand-mark b{color:var(--lime)}.brand-icon{font-size:27px;color:var(--lime)}.brand-mark.large{font-size:12px}.brand-mark.large .brand-icon{font-size:33px}.nav-tag{font-size:10px;letter-spacing:2px;color:#d8dccd;display:flex;align-items:center;gap:9px}.nav-tag span,.eyebrow-line{width:7px;height:7px;border-radius:50%;background:var(--lime);box-shadow:0 0 13px #d5f36c}.hero-copy{position:absolute;left:9.2%;top:21%;}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--lime);display:flex;align-items:center;gap:10px}.hero-copy h1{font:600 clamp(54px,7vw,100px)/.91 'Space Grotesk',sans-serif;letter-spacing:-6px;margin:26px 0 20px}.hero-copy h1 em,.modal-card h2 em{font-family:Georgia,serif;font-weight:400;color:var(--lime);letter-spacing:-4px}.hero-copy p{font-size:14px;line-height:1.75;color:#c2c7b9;margin:0}.menu-actions{display:flex;gap:24px;align-items:center;margin-top:27px}.primary-button{background:var(--lime);color:#182117;border:0;padding:16px 19px;font:700 10px 'DM Sans',sans-serif;letter-spacing:1.35px;transition:transform .2s,background .2s;min-width:174px}.primary-button:hover{transform:translateY(-2px);background:#e5ff86}.primary-button span{font-size:17px;margin-left:20px;vertical-align:-2px}.text-button{background:none;border:0;color:#e5e8db;font-size:10px;font-weight:600;letter-spacing:1.2px;padding:12px 0}.text-button span{color:var(--lime);padding-left:8px}.feature-row{display:flex;align-items:center;gap:19px;margin-top:38px}.feature-row div{display:flex;flex-direction:column;gap:4px}.feature-row b{font:600 19px 'Space Grotesk'}.feature-row span{font-size:8px;letter-spacing:1.8px;color:#adb5a5}.feature-row i{height:28px;width:1px;background:#546052}.menu-controls{position:absolute;right:6.2%;top:18%;width:min(310px,27%);min-width:270px;padding:21px;background:rgba(11,19,15,.72);border:1px solid rgba(232,241,213,.15);backdrop-filter:blur(15px)}.field-group{margin-bottom:20px}.field-group:last-child{margin:0}.field-group>label{display:block;color:#a6ae9f;font-size:8px;letter-spacing:1.7px;margin-bottom:10px}.choice-row{display:flex;gap:7px}.choice{width:50%;height:38px;display:flex;align-items:center;justify-content:center;gap:8px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.1);color:#b4bdad;font-size:9px;letter-spacing:1px}.choice.active{border-color:var(--lime);color:var(--lime);background:rgba(213,243,108,.07)}.choice-icon{font-size:14px}.field-group select{width:100%;height:40px;padding:0 10px;color:#e8e9dc;background:#17221a;border:1px solid rgba(255,255,255,.13);font-size:10px;outline:none}.map-picker{display:flex;flex-direction:column;gap:5px}.map-option{width:100%;height:47px;display:flex;align-items:center;text-align:left;gap:9px;border:1px solid transparent;background:rgba(255,255,255,.035);color:#aeb6a6;padding:5px 9px}.map-option.active{border-color:rgba(213,243,108,.64);background:rgba(213,243,108,.07);color:var(--paper)}.map-icon{width:28px;height:28px;display:grid;place-items:center;background:rgba(213,243,108,.1);color:var(--lime);font-size:18px}.savanna-icon{color:#edbd68;background:rgba(237,189,104,.12)}.temple-icon{color:#91d3bb;background:rgba(145,211,187,.12)}.map-option>span:nth-child(2){display:flex;flex-direction:column;gap:3px;flex:1}.map-option b{font-size:8px;letter-spacing:1px}.map-option small{font-size:8px;color:#97a193}.map-option i{font-style:normal;font:10px 'Space Grotesk';color:#85917f}.menu-footer{position:absolute;bottom:4%;left:6.2%;right:6.2%;display:flex;justify-content:space-between;font-size:8px;color:#bbc1b3;letter-spacing:1px}.menu-footer i{font-style:normal;color:var(--lime);padding:0 8px}.menu-footer b{color:var(--lime);margin-left:8px}.hero-index{position:absolute;right:2.1%;bottom:16%;font:24px 'Space Grotesk';writing-mode:vertical-rl;color:var(--lime)}.hero-index span{font-size:10px;color:#b1b8aa;margin:9px 0}
#top-hud{top:0;left:0;right:0;height:86px;padding:18px 4%;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(7,12,10,.88),transparent)}.match-center{text-align:center;min-width:150px}.round-line{display:flex;justify-content:center;gap:9px;align-items:center;font-size:8px;letter-spacing:1.4px;color:#d9dfd0}.round-dash{width:19px;height:1px;background:var(--lime)}#timer{font:600 25px 'Space Grotesk';letter-spacing:1px;margin:3px 0;color:var(--paper)}#phase-label{font-size:8px;letter-spacing:1.7px;color:var(--lime)}.scoreboard{display:flex;align-items:center;gap:12px}.score-team{display:flex;align-items:center;gap:8px;font-size:8px;letter-spacing:1.2px}.score-team b{font:600 16px 'Space Grotesk';margin-left:3px}.team-dot{width:6px;height:6px;background:#9bd5ae;border-radius:50%}.seeker-score .team-dot{background:#ff8269}.score-divider{font-size:10px;color:#718074}
#objective-card{left:4%;top:25%;display:flex;flex-direction:column;gap:7px;max-width:230px;padding:15px 18px;background:linear-gradient(90deg,rgba(13,20,17,.82),transparent);border-left:2px solid var(--lime)}#objective-card .eyebrow{font-size:8px}#objective-title{font:600 20px 'Space Grotesk'}#objective-copy{font-size:10px;color:#c0c8b7}.alive-line{font-size:9px;letter-spacing:.5px;color:#cad2c3;margin-top:8px}.alive-pulse{width:6px;height:6px;border-radius:50%;display:inline-block;background:var(--lime);margin-right:5px;box-shadow:0 0 8px var(--lime)}#ability-card{bottom:8%;left:50%;transform:translateX(-50%);min-width:245px;display:flex;align-items:center;gap:11px;padding:10px 13px;background:rgba(10,16,13,.83);border:1px solid rgba(226,237,211,.17)}.ability-key{width:33px;height:33px;display:grid;place-items:center;border:1px solid rgba(213,243,108,.65);color:var(--lime);font:600 15px 'Space Grotesk'}.ability-text{display:flex;flex-direction:column;gap:4px;flex:1}.ability-text strong{font-size:8px;letter-spacing:1.1px}.ability-text span{font-size:7px;letter-spacing:1.3px;color:#9da99c}#ability-meter{width:54px;height:3px;background:#354138}#ability-meter span{display:block;width:100%;height:100%;background:var(--lime);transition:width .1s}#crosshair{position:absolute;left:50%;top:50%;z-index:2;transform:translate(-50%,-50%);width:13px;height:13px;opacity:.8;pointer-events:none}#crosshair i,#crosshair b{position:absolute;background:rgba(255,255,236,.85)}#crosshair i{height:1px;width:13px;top:6px}#crosshair b{height:13px;width:1px;left:6px}#pointer-hint{position:absolute;z-index:3;left:50%;top:58%;transform:translateX(-50%);display:flex;flex-direction:column;text-align:center;gap:5px;color:#fff;text-shadow:0 1px 5px #000;font-size:9px;letter-spacing:2px;pointer-events:none}#pointer-hint small{font-size:7px;color:#d1d6c9}#blackout{position:absolute;inset:0;z-index:4;background:#050806;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}#blackout p{font:600 12px 'Space Grotesk';letter-spacing:3px;margin:16px 0 7px;color:var(--lime)}#blackout>span{font-size:11px;color:#9eaa9b}#blackout>span b{color:#fff;font-size:16px;margin-left:5px}.blackout-mark{font-size:55px;color:#354238}#status-toast{position:absolute;z-index:5;top:19%;left:50%;transform:translateX(-50%);background:rgba(12,18,14,.9);padding:12px 20px;border:1px solid rgba(213,243,108,.5);font-size:10px;letter-spacing:1.1px;color:var(--lime);white-space:nowrap;animation:toastIn .25s ease}@keyframes toastIn{from{opacity:0;transform:translate(-50%,-8px)}to{opacity:1;transform:translate(-50%,0)}}#feed{top:17%;right:4%;display:flex;flex-direction:column;gap:7px;text-align:right;font-size:9px;color:#ebeadf;text-shadow:0 1px 4px #000}.feed-item{padding:7px 10px;background:rgba(10,16,13,.67);border-right:2px solid #ef8066}#sound-toggle{position:absolute;z-index:4;bottom:4%;right:4%;border:1px solid rgba(255,255,255,.3);background:rgba(11,18,14,.7);border-radius:50%;width:32px;height:32px;display:grid;place-items:center;color:#e5e8dc;cursor:pointer}
.modal-screen{position:absolute;inset:0;z-index:8;background:rgba(4,8,6,.76);backdrop-filter:blur(9px);display:grid;place-items:center;padding:20px}.modal-card{position:relative;width:min(520px,96vw);padding:36px 39px;background:#111b15;border:1px solid rgba(225,237,210,.16);box-shadow:0 25px 100px #0008}.modal-card h2{font:600 43px/.96 'Space Grotesk';letter-spacing:-2.5px;margin:16px 0}.modal-card h2 em{letter-spacing:-2px}.modal-card p{color:#b3beb1;font-size:12px;line-height:1.7}.close-modal{position:absolute;right:15px;top:12px;background:none;border:0;color:#aeb9ac;font-size:25px}.guide-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 23px;margin:25px 0}.guide-grid b{font-size:9px;color:var(--lime);letter-spacing:1px}.guide-grid p{margin:7px 0 0;font-size:10px}.result-card{text-align:center}.result-card .eyebrow{justify-content:center}.result-card h2{font-size:48px}.result-score{display:flex;justify-content:center;gap:16px;align-items:center;margin:24px 0}.result-score span{font-size:9px;letter-spacing:1px;color:#aeb9ac}.result-score b{font:600 18px 'Space Grotesk';color:var(--paper);margin-left:7px}.result-score i{font-style:normal;color:var(--lime)}.pause-card{text-align:center;width:min(400px,95vw)}.pause-card .eyebrow{justify-content:center}.pause-card .text-button{display:block;margin:10px auto 0}.modal-card .primary-button{margin-top:8px}#pause-screen .modal-card p{margin-bottom:22px}
#game-wrap.role-seeker #crosshair{opacity:1}#game-wrap.role-seeker #objective-card{border-left-color:#ff8269}#game-wrap.role-seeker .alive-pulse{background:#ff8269;box-shadow:0 0 8px #ff8269}#game-wrap.monkey #ability-key{border-color:#b8d5a5;color:#b8d5a5}
@media(max-width:850px){.hero-copy{left:6%;top:17%}.hero-copy h1{font-size:68px}.menu-controls{right:4%;top:47%;width:285px}.hero-index{display:none}.menu-footer{left:5%;right:5%}.menu-nav{left:5%;right:5%}}@media(max-width:600px){#start-screen{background-position:57% center}.menu-nav{top:3%}.nav-tag{font-size:7px}.hero-copy{top:13%;left:7%}.hero-copy h1{font-size:54px;letter-spacing:-3px;margin:16px 0}.hero-copy p{font-size:11px}.menu-actions{margin-top:17px;gap:12px}.primary-button{padding:13px 12px;min-width:145px;font-size:9px}.primary-button span{margin-left:8px}.feature-row{margin-top:22px;gap:12px}.feature-row b{font-size:15px}.feature-row span{font-size:7px}.menu-controls{top:auto;bottom:11%;left:5%;right:5%;width:auto;min-width:0;padding:13px 15px}.field-group{margin-bottom:12px}.field-group>label{margin-bottom:7px}.field-group select{height:34px}.map-option{height:40px}.menu-footer{bottom:3%;font-size:6px}.menu-footer span:last-child{display:none}.choice{height:32px}.modal-card{padding:29px 23px}.modal-card h2{font-size:37px}.guide-grid{gap:12px}.guide-grid p{font-size:9px}#top-hud{height:73px;padding:12px 3%}.brand-mark{font-size:8px;gap:5px}.brand-icon{font-size:22px}.match-center{min-width:115px}.round-line{font-size:6px;gap:5px}.scoreboard{gap:5px}.score-team{font-size:6px;gap:4px}.score-team b{font-size:13px}.score-divider{font-size:8px}#objective-card{top:17%;left:3%;padding:10px 12px;max-width:190px}#objective-title{font-size:17px}#ability-card{bottom:5%;min-width:220px}.hero-index{display:none}}@media(max-height:700px) and (min-width:601px){.hero-copy{top:17%}.menu-controls{top:13%;transform:scale(.88);transform-origin:top right}.hero-copy h1{font-size:72px;margin:16px 0}.feature-row{margin-top:23px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $=id=>document.getElementById(id), canvas=$('game-canvas');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5ad');scene.fog=new THREE.FogExp2('#a9c5ad',.014);
const camera=new THREE.PerspectiveCamera(65,innerWidth/innerHeight,.1,220);const clock=new THREE.Clock();
const hemi=new THREE.HemisphereLight('#d5e6ca','#35402b',2.1);scene.add(hemi);const sun=new THREE.DirectionalLight('#fff0cb',3.3);sun.position.set(-18,30,12);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-42;sun.shadow.camera.right=42;sun.shadow.camera.top=42;sun.shadow.camera.bottom=-42;scene.add(sun);
let mapName='jungle',role='hider',animal='chameleon',gameState='menu',round=1,hiderWins=0,seekerWins=0,phase='hide',phaseTime=30,player,seekers=[],hiders=[],allActors=[],obstacles=[],decor=[],keys={},yaw=0,pitch=.18,pointer=false,ended=false,toastTimer=0,roundDelay=0,abilityTime=0,abilityCooldown=0,roarCooldown=0,sprintTime=0,sprintCooldown=0,tagCooldown=0,feedItems=[],soundOn=true,audioCtx=null;
const MAPS={jungle:{label:'TROPICAL JUNGLE',ground:'#44583a',fog:'#91a886',sky:'#9eb8a1',ambient:'#d9e8ca',sun:'#ffe2ae',density:1.28},savanna:{label:'AFRICAN SAVANNA',ground:'#a58b51',fog:'#d4b87b',sky:'#c9c491',ambient:'#eee0b4',sun:'#fff0c1',density:.78},temple:{label:'ANCIENT TEMPLE',ground:'#596b5f',fog:'#82958a',sky:'#abb9ad',ambient:'#d9dfc8',sun:'#d6e5d1',density:.96}};
const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z), v=(x,y,z)=>new THREE.Vector3(x,y,z);
function setMap(name){mapName=name;const m=MAPS[name];scene.background.set(m.sky);scene.fog.color.set(m.fog);scene.fog.density=name==='savanna'?.009:.014;hemi.color.set(m.ambient);sun.color.set(m.sun);$('map-label').textContent=m.label;}
function mat(color,roughness=.92){return new THREE.MeshStandardMaterial({color,roughness});}
const mats={bark:mat('#554333'),leaf:mat('#41654a'),leaf2:mat('#617a48'),grass:mat('#758347'),dry:mat('#c1a55e'),stone:mat('#77786a'),moss:mat('#526c55'),sand:mat('#c1a36a'),ruin:mat('#8b816d'),dark:mat('#202821')};
function mesh(geo,material,parent=scene){const o=new THREE.Mesh(geo,material);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function groundTile(x,z,w,d,color,y=0){const o=mesh(new THREE.BoxGeometry(w,.12,d),mat(color));o.position.set(x,y-.07,z);o.receiveShadow=true;return o;}
function addObstacle(x,z,r,kind='solid'){obstacles.push({x,z,r,kind});}
function tree(x,z,scale=1,savanna=false){const trunk=mesh(new THREE.CylinderGeometry(.28*scale,.42*scale,3.8*scale,7),mats.bark);trunk.position.set(x,1.9*scale,z);if(savanna){const crown=mesh(new THREE.SphereGeometry(2.1*scale,8,6),mats.leaf2);crown.scale.set(1.45,.42,1.12);crown.position.set(x,4.35*scale,z);}else{for(let i=0;i<3;i++){let c=mesh(new THREE.ConeGeometry((2.3-i*.42)*scale,2.4*scale,7),i%2?mats.leaf:mats.leaf2);c.position.set(x,3.25*scale+i*1.12*scale,z);}}addObstacle(x,z,.65*scale,'tree');}
function grassClump(x,z,scale=1,color){const g=new THREE.Group();const m=color||mats.grass;for(let i=0;i<5;i++){const blade=mesh(new THREE.ConeGeometry(.12*scale,rand(.65,1.25)*scale,4),m,g);blade.position.set(rand(-.3,.3)*scale,.35*scale+Math.random()*.25*scale,rand(-.3,.3)*scale);blade.rotation.z=rand(-.35,.35);}g.position.set(x,0,z);scene.add(g);decor.push(g);}
function rock(x,z,scale=1,material=mats.stone){const r=mesh(new THREE.DodecahedronGeometry(scale,0),material);r.scale.set(1.3,.8,1);r.position.set(x,.55*scale,z);addObstacle(x,z,.85*scale,'solid');}
function ruin(x,z){const stone=mat('#928974');const post=mesh(new THREE.BoxGeometry(.8,4,.9),stone);post.position.set(x,2,z);addObstacle(x,z,.65,'solid');const cap=mesh(new THREE.BoxGeometry(1.2,.35,1.35),stone);cap.position.set(x,4.1,z);}
function templeLayout(){const stone=mat('#8c836e');for(let x=-13;x<=13;x+=5){for(let z=-10;z<=10;z+=5){if(Math.abs(x)<4&&Math.abs(z)<4)continue;const col=mesh(new THREE.BoxGeometry(.7,rand(2,4.8),.75),stone);col.position.set(x,col.geometry.parameters.height/2,z);col.rotation.y=rand(-.12,.12);addObstacle(x,z,.65,'solid');if(Math.random()>.35){const block=mesh(new THREE.BoxGeometry(2.1,.55,1.7),stone);block.position.set(x+rand(-.5,.5),.5,z+rand(-1,1));addObstacle(block.position.x,block.position.z,1,'solid');}}}
 for(let x=-10;x<=10;x+=10){const arch=new THREE.Group();for(let z of [-3,3]){const p=mesh(new THREE.BoxGeometry(.8,3.5,.8),stone,arch);p.position.set(0,1.75,z);addObstacle(x,z,.6,'solid');}const top=mesh(new THREE.BoxGeometry(.9,.8,6.8),stone,arch);top.position.y=3.65;arch.position.x=x;scene.add(arch);}
 for(let i=0;i<65;i++)if(Math.random()>.35){const x=rand(-24,24),z=rand(-24,24);const b=mesh(new THREE.BoxGeometry(rand(.5,2),rand(.2,.8),rand(.6,1.5)),Math.random()>.5?mats.ruin:mats.moss);b.position.set(x,.25,z);b.rotation.y=rand(0,Math.PI);}
}
function buildWorld(){while(scene.children.length>0){const o=scene.children[0];scene.remove(o);}scene.add(hemi,sun);obstacles=[];decor=[];const m=MAPS[mapName];const floor=mesh(new THREE.PlaneGeometry(90,90),mat(m.ground));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;floor.position.y=-.14;groundTile(0,0,90,90,m.ground,-.02);
 // A looping trail gives the arena readable landmarks and a clear play space.
 const pathMat=mat(mapName==='jungle'?'#82714c':mapName==='savanna'?'#c3a76a':'#777363');const path=mesh(new THREE.RingGeometry(14,17,80),pathMat);path.rotation.x=-Math.PI/2;path.position.y=-.04;
 if(mapName==='jungle'){for(let i=0;i<105;i++){let x=rand(-37,37),z=rand(-37,37);if(Math.hypot(x,z)<13)continue;tree(x,z,rand(.72,1.38));}for(let i=0;i<360;i++){let x=rand(-39,39),z=rand(-39,39);if(Math.hypot(x,z)<9)continue;grassClump(x,z,rand(.55,1.15),Math.random()>.5?mats.leaf:mats.grass);}for(let i=0;i<22;i++)rock(rand(-36,36),rand(-36,36),rand(.45,1.2),mats.moss);
 }else if(mapName==='savanna'){for(let i=0;i<37;i++){let x=rand(-38,38),z=rand(-38,38);if(Math.hypot(x,z)<14)continue;tree(x,z,rand(.9,1.45),true);}for(let i=0;i<290;i++){let x=rand(-39,39),z=rand(-39,39);if(Math.hypot(x,z)<8)continue;grassClump(x,z,rand(.6,1.15),Math.random()>.5?mats.dry:mats.grass);}for(let i=0;i<13;i++)rock(rand(-34,34),rand(-34,34),rand(.7,1.8),mats.stone);
