function endRound(winner){if(ended)return;ended=true;gameState='result';if(winner==='hider')hiderWins++;else seekerWins++;$('hider-score').textContent=hiderWins;$('seeker-score').textContent=seekerWins;$('result-hider-score').textContent=hiderWins;$('result-seeker-score').textContent=seekerWins;const gameOver=hiderWins>=3||seekerWins>=3;$('result-eyebrow').textContent=gameOver?'MATCH COMPLETE':'ROUND COMPLETE';$('result-title').innerHTML=gameOver?'The wild<br><em>is yours.</em>':winner==='hider'?'The wild<br><em>held its breath.</em>':'The hunt<br><em>is complete.</em>';$('result-copy').textContent=winner==='hider'?'At least one hider survived the four-minute hunt.':'The seekers caught every last hider.';$('next-round').innerHTML=gameOver?'RETURN TO MENU <span>↗</span>':'NEXT ROUND <span>↗</span>';if(gameOver)$('next-round').onclick=()=>{round=1;hiderWins=0;seekerWins=0;gameState='menu';$('result-screen').classList.add('hidden');$('start-screen').classList.remove('hidden');document.exitPointerLock?.();};else $('next-round').onclick=()=>{round++;mapName=['jungle','savanna','temple'][(round-1)%3];resetGame();};$('result-screen').classList.remove('hidden');document.exitPointerLock?.();sound(winner==='hider'?'win':'lose');}
function sound(type){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=type==='start'?260:type==='win'?520:type==='tag'?130:190;gain.gain.setValueAtTime(.05,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.22);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.23);osc.onended=()=>ctx.close();}catch{}}
function activateAbility(){if(gameState!=='playing'||abilityCooldown>0)return;if(role==='seeker'&&animal==='lion'){roarReveal=5;roarCooldown=16;abilityCooldown=16;feed('Lion roar revealed moving prey nearby!');toast('ROAR! Moving prey revealed.');sound('start');for(const a of living(hiders)){if(a.position.distanceTo(player.position)<18&&a.userData.stepMoving)a.userData.revealed=4;}return;}if(role==='hider'&&animal==='chameleon'){abilityTime=10;abilityCooldown=18;const m=player.userData.bodyMat;m.transparent=true;m.opacity=.25;player.userData.camouflaged=true;toast('Camouflage active for 10 seconds.');return;}if(role==='hider'&&animal==='monkey'){const tree=trees.sort((a,b)=>a.distanceTo(player.position)-b.distanceTo(player.position))[0];if(tree&&tree.distanceTo(player.position)<9){player.userData.climb=8;player.position.y=2.8;abilityTime=8;abilityCooldown=20;toast('You climbed into the canopy.');}else toast('Get closer to a tree to climb.');return;}abilityTime=3.5;abilityCooldown=10;toast(role==='seeker'?'Cheetah sprint!':'Sprint!');}
function doTag(actor){if(!actor||!actor.userData.alive)return;actor.userData.alive=false;actor.visible=false;actor.userData.tagCooldown=99;feed(`${actor.userData.kind} was caught.`);sound('tag');if(actor===player){toast('Caught! You are spectating.');player.userData.isPlayer=false;player=null;const next=living(role==='hider'?hiders:seekers)[0];if(next){player=next;player.userData.isPlayer=true;camera.position.set(player.position.x,player.position.y+1.55,player.position.z);}}if(!living(hiders).length)endRound('seeker');}
function moveActor(actor,dir,speed,dt){if(dir.lengthSq()<.001)return;dir.normalize();actor.position.x+=dir.x*speed*dt;actor.position.z+=dir.z*speed*dt;actor.position.x=clamp(actor.position.x,-23,23);actor.position.z=clamp(actor.position.z,-23,23);actor.rotation.y=Math.atan2(dir.x,dir.z);actor.userData.step+=dt*speed*2.7;actor.userData.stepMoving=true;for(const leg of actor.userData.legs)leg.rotation.x=Math.sin(actor.userData.step+(leg.position.x+leg.position.z)*3)*.65;}
function updateAI(dt){const liveSeekers=living(seekers),liveHiders=living(hiders);for(const h of liveHiders){if(!h.userData.ai||phase==='hide')continue;let target=null,nearest=Infinity;for(const s of liveSeekers){const d=h.position.distanceTo(s.position);if(d<nearest){nearest=d;target=s;}}let dir=new THREE.Vector3();if(nearest<10&&phase==='hunt'){dir.set(h.position.x-target.position.x,0,h.position.z-target.position.z);if(nearest<1.4)doTag(h);}else{h.userData.wander=(h.userData.wander||0)-dt;if(h.userData.wander<=0||!h.userData.aiTarget){h.userData.aiTarget=new THREE.Vector3(rand(-19,19),0,rand(-19,19));h.userData.wander=rand(2,5);}dir.subVectors(h.userData.aiTarget,h.position);if(dir.length()<1)h.userData.aiTarget=null;}moveActor(h,dir,h.userData.speed*(nearest<10?1.18:.58),dt);}
 for(const s of liveSeekers){if(!s.userData.ai||phase==='hide')continue;let target=null,near=Infinity;for(const h of liveHiders){if(h.userData.camouflaged&&h.position.distanceTo(s.position)>3.2)continue;const d=s.position.distanceTo(h.position);if(d<near){target=h;near=d;}}if(target){const dir=new THREE.Vector3().subVectors(target.position,s.position);if(near<1.65)doTag(target);moveActor(s,dir,s.userData.speed,dt);}}
}

