 for(const s of liveSeekers){if(!s.userData.ai||phase==='hide')continue;let target=null,near=Infinity;for(const h of liveHiders){if(h.userData.camouflaged&&h.position.distanceTo(s.position)>3.2)continue;const d=s.position.distanceTo(h.position);if(d<near){target=h;near=d;}}if(target){const dir=new THREE.Vector3().subVectors(target.position,s.position);if(near<1.65)doTag(target);moveActor(s,dir,s.userData.speed,dt);}}
