function tick(dt){elapsed+=dt;if(gameState==='playing'){if(phaseTime>0){phaseTime-=dt;if(phaseTime<=0){if(phase==='hide')startHunt();else{endRound(living(hiders).length?'hider':'seeker');}}}if(abilityCooldown>0)abilityCooldown=Math.max(0,abilityCooldown-dt);if(abilityTime>0){abilityTime=Math.max(0,abilityTime-dt);if(abilityTime===0&&player){if(player.userData.camouflaged){player.userData.camouflaged=false;player.userData.bodyMat.opacity=1;player.userData.bodyMat.transparent=false;}if(player.userData.climb){player.userData.climb=0;player.position.y=0;}}}if(roarReveal>0)roarReveal-=dt;if(player&&player.userData.alive){const speed=player.userData.speed;forward.set(-Math.sin(yaw),0,-Math.cos(yaw));right.set(Math.cos(yaw),0,-Math.sin(yaw));move.set(0,0,0);if(keys.has('KeyW')||keys.has('ArrowUp'))move.add(forward);if(keys.has('KeyS')||keys.has('ArrowDown'))move.sub(forward);if(keys.has('KeyD')||keys.has('ArrowRight'))move.add(right);if(keys.has('KeyA')||keys.has('ArrowLeft'))move.sub(right);let factor=1;if((keys.has('ShiftLeft')||keys.has('ShiftRight'))&&abilityTime>0)factor=1.65;moveActor(player,move,speed*factor,dt);if(player.userData.climb&&player.position.y===0)player.position.y=2.8;if(player.userData.climb&&player.position.y!==0)player.position.y=2.8;camera.position.set(player.position.x,player.position.y+1.45,player.position.z);camera.rotation.order='YXZ';camera.rotation.set(pitch,yaw,0);}updateAI(dt);for(const a of allActors){a.userData.stepMoving=false;if(a.userData.revealed>0)a.userData.revealed-=dt;}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('status-toast').classList.add('hidden');}for(const item of feedItems)item.t-=dt;feedItems=feedItems.filter(x=>x.t>0);$('feed').innerHTML=feedItems.map(x=>`<div>${x.msg}</div>`).join('');updateHud();}else if(gameState==='menu'){camera.position.set(Math.sin(elapsed*.08)*1,2.1,10);camera.lookAt(0,1.3,0);}renderer.render(scene,camera);}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,(now-lastTime)/1000||0);lastTime=now;tick(dt);}
function startPointer(){if(gameState==='playing'&&canvas.requestPointerLock)canvas.requestPointerLock();}
canvas.addEventListener('click',startPointer);
document.addEventListener('pointerlockchange',()=>{$('pointer-hint').classList.toggle('hidden',document.pointerLockElement===canvas||gameState!=='playing');});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement!==canvas||gameState!=='playing')return;yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0018,-1.05,1.05);});
document.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Escape'&&gameState==='playing'){gameState='paused';$('pause-screen').classList.remove('hidden');$('pointer-hint').classList.add('hidden');document.exitPointerLock?.();return;}if(gameState!=='playing')return;keys.add(e.code);if(e.repeat)return;if(e.code==='KeyE')tryTag();if(e.code==='KeyQ'&&role==='seeker'&&animal==='lion')activateAbility();if(e.code==='KeyC'&&role==='hider'&&animal==='chameleon')activateAbility();if(e.code==='Space'){if(role==='hider'&&animal==='monkey')activateAbility();else if(player&&player.position.y===0){player.position.y=.6;setTimeout(()=>{if(player&&player.position.y===.6)player.position.y=0;},420);}}if((e.code==='ShiftLeft'||e.code==='ShiftRight')&&abilityCooldown<=0&&(role==='seeker'&&animal==='cheetah'||role==='hider'&&!['chameleon','monkey'].includes(animal)))activateAbility();});
document.addEventListener('keyup',e=>keys.delete(e.code));
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});
$('play-button').addEventListener('click',()=>resetGame());$('guide-play').addEventListener('click',()=>{$('instructions-screen').classList.add('hidden');});$('how-button').addEventListener('click',()=>$('instructions-screen').classList.remove('hidden'));$('close-how').addEventListener('click',()=>$('instructions-screen').classList.add('hidden'));
$('role-picker').addEventListener('click',e=>{const b=e.target.closest('[data-role]');if(!b)return;role=b.dataset.role;document.querySelectorAll('#role-picker .choice').forEach(x=>x.classList.toggle('active',x===b));const select=$('animal-select');select.innerHTML=role==='hider'?'<option value="chameleon">Chameleon · camouflage</option><option value="monkey">Monkey · tree climber</option><option value="rabbit">Rabbit · quick prey</option><option value="fox">Fox · swift prey</option><option value="raccoon">Raccoon · woodland prey</option><option value="deer">Deer · fast prey</option><option value="boar">Boar · sturdy prey</option><option value="tortoise">Tortoise · camouflage</option><option value="owl">Owl · silent prey</option>':'<option value="cheetah">Cheetah · sprint</option><option value="lion">Lion · reveal roar</option>';animal=select.value;});
$('animal-select').addEventListener('change',e=>animal=e.target.value);$('map-picker').addEventListener('click',e=>{const b=e.target.closest('[data-map]');if(!b)return;mapName=b.dataset.map;document.querySelectorAll('.map-option').forEach(x=>x.classList.toggle('active',x===b));});
$('resume-button').addEventListener('click',()=>{gameState='playing';$('pause-screen').classList.add('hidden');startPointer();});$('quit-button').addEventListener('click',()=>{gameState='menu';$('pause-screen').classList.add('hidden');$('top-hud').classList.add('hidden');$('objective-card').classList.add('hidden');$('ability-card').classList.add('hidden');$('feed').classList.add('hidden');$('sound-toggle').classList.add('hidden');$('start-screen').classList.remove('hidden');document.exitPointerLock?.();});
$('sound-toggle').addEventListener('click',e=>{e.currentTarget.classList.toggle('muted');toast(e.currentTarget.classList.contains('muted')?'Sound muted':'Sound on');});
buildWorld();requestAnimationFrame(animate);

