 function buildJungle(p){for(let i=0;i<34;i++){const a=rand(0,Math.PI*2),r=rand(7,22),x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<5)continue;const trunk=mesh(new THREE.CylinderGeometry(.22,.38,rand(4,7),7),mat('#55422e'));trunk.position.set(x,2,z);addWorld(trunk);const crown=mesh(new THREE.SphereGeometry(rand(1.7,2.7),8,7),mat(i%2?'#355a31':'#466b37'));crown.position.set(x,rand(4,6),z);addWorld(crown);trees.push(new THREE.Vector3(x,0,z));for(let j=0;j<3;j++){const f=mesh(new THREE.ConeGeometry(.45,rand(1.1,2),5),mat('#506c38'));f.position.set(x+rand(-1.5,1.5),.8,z+rand(-1.5,1.5));addWorld(f);}}}
